<?php
declare(strict_types=1);
namespace App\Services; use App\Core\Database; use App\Repositories\ExpenseRepository;
final class ExpenseService { public function create(array $d,array $actor):int{$pdo=Database::connection();$pdo->beginTransaction();try{$id=(new ExpenseRepository())->create($d);if(($d['status']??'posted')==='posted')$pdo->prepare('UPDATE accounts SET current_balance=current_balance-?,updated_at=NOW() WHERE id=?')->execute([$d['amount'],$d['account_id']]);$this->audit($pdo,$actor['id'],'create','expenses',$id,null,$d);$pdo->commit();return $id;}catch(\Throwable $e){$pdo->rollBack();throw $e;}} public function update(int $id,array $d,array $actor):void{$pdo=Database::connection();$pdo->beginTransaction();try{$old=(new ExpenseRepository())->find($id);if(!$old)throw new \RuntimeException('Expense not found');if(($old['status']??'posted')==='posted'){ $pdo->prepare('UPDATE accounts SET current_balance=current_balance+?,updated_at=NOW() WHERE id=?')->execute([$old['amount'],$old['account_id']]); } if(($d['status']??'posted')==='posted'){ $pdo->prepare('UPDATE accounts SET current_balance=current_balance-?,updated_at=NOW() WHERE id=?')->execute([$d['amount'],$d['account_id']]); }(new ExpenseRepository())->update($id,$d);$this->audit($pdo,$actor['id'],'update','expenses',$id,$old,$d);$pdo->commit();}catch(\Throwable $e){$pdo->rollBack();throw $e;}} public function delete(int $id,array $actor):void{$pdo=Database::connection();$pdo->beginTransaction();try{$old=(new ExpenseRepository())->find($id);if(!$old)throw new \RuntimeException('Expense not found');(new ExpenseRepository())->delete($id);if(($old['status']??'posted')==='posted')$pdo->prepare('UPDATE accounts SET current_balance=current_balance+?,updated_at=NOW() WHERE id=?')->execute([$old['amount'],$old['account_id']]);$this->audit($pdo,$actor['id'],'delete','expenses',$id,$old,null);$pdo->commit();}catch(\Throwable $e){$pdo->rollBack();throw $e;}} private function audit($pdo,int $uid,string $action,string $entity,int $id,$old,$new):void{$s=$pdo->prepare('INSERT INTO audit_logs(user_id,action,entity,entity_id,old_values,new_values,ip_address,user_agent,created_at) VALUES(?,?,?,?,?,?,?,?,NOW())');$s->execute([$uid,$action,$entity,$id,$old?json_encode($old):null,$new?json_encode($new):null,$_SERVER['REMOTE_ADDR']??null,$_SERVER['HTTP_USER_AGENT']??null]);}}
